INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_4_0','奉试诏用拓拔思恭为京北收复都统','李琪','五代','飞骑经巴栈，
鸿恩及夏台。
将从天上去，
人自日边来。
此处金门远，
何时玉辇回。
早平关右贼，
莫待诏书催。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_1','题广爱寺楞伽山','李琪','五代','善高天外远，
方丈海中遥。
自有山神护，
应无劫火烧。
坏文侵古壁，
飞剑出寒霄。
何似苍苍色，
严妆十七朝。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_2','句','李琪','五代','哀痛不下诏，
登封谁上书。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_4_3','奉和圣制送张说上集贤学士赐宴','李皓','唐','偃武尧风接，
崇文汉道恢。
集贤更内殿，
清选自中台。
佐命留侯业，
词华博物才。
天厨千品降，
御酒百壶催。
鹓鹭方成列，
神仙喜暂陪。
复欣同拜首，
叨此颂良哉。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_4','赠毛仙翁','李程','中唐','茫茫尘累愧腥膻，
强把蜉蝣望列仙。
闲指紫霄峰下路，
却归白鹿洞中天。
吹箫凤去经何代，
茹玉方传得几年。
他日更来人世看，
又应东海变桑田。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_5','玉壶冰','李程','中唐','琢玉性惟坚，
成壶体更圆。
虚心含众象，
应物受寒泉。
温润资天质，
清贞禀自然。
日融光乍散，
雪照色逾鲜。
至鉴功宁宰，
无私照岂偏。
明将水镜对，
白与粉闱连。
拂拭终为美，
提携伫见传。
勿令毫发累，
遗恨鲍公篇。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_6','观庆云图','李程','中唐','五云从表瑞，
藻绘宛成图。
柯叶何时改，
丹青此不渝。
非烟色尚丽，
似盖状应殊。
渥彩看犹在，
轻阴望已无。
方将遇翠幄，
那羡起苍梧。
欲识从龙处，
今逢圣合符。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_7','春台晴望','李程','中唐','曲台送春目，
景物丽新晴。
霭霭烟收翠，
忻忻木向荣。
静看迟日上，
闲爱野云平。
风慢游丝转，
天开远水明。
登高尘虑息，
观徼道心清。
更有迁乔意，
翩翩出谷莺。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_8','赋得竹箭有筠','李程','中唐','常爱凌寒竹，
坚贞可喻人。
能将先进礼，
义与后凋邻。
冉冉犹全节，
青青尚有筠。
陶钧二仪内，
柯叶四时春。
待凤花仍吐，
停霜色更新。
方持不易操，
对此欲观身。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_9','长至日上公献寿','李竦','中唐','候晓金门辟，
乘时玉历长。
羽仪瞻上宰，
云物丽初阳。
汉礼方传佩，
尧年正捧觞。
日行临观阙，
帝锡洽圭璋。
盛美超三代，
洪休降百祥。
自怜朝末坐，
空此咏无疆。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_10','赋得西戎献白玉环','李竦','中唐','当时无外守，
方物四夷通。
列土金河北，
朝天玉塞东。
自将荆璞比，
不与郑环同。
正朔虽传汉，
衣冠尚带戎。
幸承提佩宠，
多愧琢磨功。
绝域知文教，
争趋上国风。',NULL,'','{"preface": "", "note": ""}','排律','hefengbao/jingmo-data3'),
('rd3_4_11','卫叔卿不宾汉武帝','李翔','唐','銮殿仙卿顿紫云，
武皇非意欲相臣。
便回太华三峰路，
不喜咸阳万乘春。
涉险漫劳中禁使，
投壶多是上清人。
犹教度世依方术，
莫恋浮荣误尔身。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_12','马明生遇王婉罗','李翔','唐','彻骨金疮分已休，
谢神妃护到灵丘。
供承洞府知何地，
洒扫云房不记秋。
金锁玉函虽照耀，
宝书真篆敢窥求。
龙胎未肯传初学，
又逐安期万里游。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_13','冯双礼珠弹云璈以答歌','李翔','唐','王母词终荐碧桃，
答歌仙子奏云璈。
调凌空洞音初起，
曲丽钧天韵更高。
霞断已翔烟际鹤，
风生欲抃海心鳌。
瑶池侍女争回首，
无限琅英坠节毛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_14','石鹤','李翔','唐','白石孤标逸鹤形，
古人随类巧安名。
岩花落处见朱顶，
夜雨来时闻唳声。
辽海未曾重寄语，
缑山今更请宽程。
若教卫懿如今在，
也遣轩车到此迎。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_15','军山前马退石','李翔','唐','山亘南丰石亘山，
石横山路马登难。
非论蹇步须回驾，
纵使追风亦解鞍。
恐是龙宫通洞府，
莫应猿岭建星坛。
何因不许超骧辈，
踏着连云大麓端。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_16','百步桥','李翔','唐','亘险凌虚百步桥，
古应从此上干霄。
不辞宛转峰千仞，
且喜分明路一条。
银汉攀缘知必到，
月宫斟酌去非遥。
牵牛漫更劳乌鹊，
岁岁填河绿顶焦。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_17','西林寺与焦鍊师赋得阶下泉','李翔','唐','回廊折旋绕空阶，
暗想翻霜泻峭崖。
蕙带客寻经远涧，
麻衣僧引到高斋。
流分晓月光难驻，
响入清琴韵易谐。
时有真官访衰病，
每同观听荡幽怀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_18','许真君铁柱','李翔','唐','恐老蛟重作患深，
独埋铁柱至如今。
根牢直下蟠江底，
势壮长留镇郡心。
神鬼每闻趋夜后，
风雷不敢犯塘阴。
无因更走横泉窟，
压断祈精气永沉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_19','严尚书重浚横泉井','李翔','唐','古甃千寻锁绿苔，
老蛟曾遁此中来。
厌聆羽客提锋入，
喜见将军仗节开。
玉液洞通甘似醴，
金瓶轮下殷如雷。
更闻堪疗群生疾，
愿倚崇栏饮一杯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_20','投龙池','李翔','唐','虎眼涡盘石窟中，
古今俱向此投龙。
奫沦不啻深千丈，
肸蚃皆应到九重。
洞穴昔闻通地府，
风云今得遇灵踪。
无因犯世间雷雨，
池面连天拔一峰。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_21','顶湖','李翔','唐','万仞峰头凿一湖，
更谁来此用功夫。
张霞鬣是星河鲤，
濯火领多日御乌。
往往风波闻下界，
时时花雨护仙都。
碧莲洞口人偷说，
知似车轮许大无？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_22','看缙云山图','李翔','唐','谓见仙都二十年，
忽逢图画顿欣然。
云岩不似人间世，
物象翻疑洞里天。
迥压鳌头当海眼，
直侵鹏路倚星躔。
顶湖纵去无多地，
空见霜流百丈泉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_23','秋日过龙兴观墨池','李翔','唐','独登仙馆欲从谁，
闻有王君旧墨池。
苔藓已侵行履迹，
洼坳犹是古来规。
竹梢声认挥毫日，
殿角阴疑洗砚时。
叹倚坛边红叶树，
霜钟欲尽下山迟。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_24','览鍊师张殷儒诗','李翔','唐','石井峰高劈曙云，
云开山露见张君。
心藏定远握中策，
袖贮怀沙江上文。
巨壑波翻鲸少敌，
老松巢迥鹤难群。
无端示我青霞句，
吟断秋风到日曛。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_25','宿西山凌云观','李翔','唐','掩映真居不易求，
自惊何路到蓬丘。
庭心月近石坛古，
海面风微山殿秋。
控鹤岭高星半隔，
伏龙岗转水分流。
胡尊纵使如今在，
谁继花姑问事由？',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_26','寄麻姑山喻供奉','李翔','唐','羽客乘风下九天，
拨云亲自拣林泉。
檐吞海魄迎真气，
路绕岩根谒古仙。
道胜早为三洞伏，
诗成曾被六宫传。
如今万事皆轻弃，
只待还丹驻鹤年。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_27','寄题寻真观','李翔','唐','见说寻真地势雄，
面临湖北倚高峰。
奔涛入夏雷声迅，
险嶂凌秋黛色浓。
坛上步虚频降鹤，
洞中投简数惊龙。
何劳更访桃源路，
水曲云深千万重。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_28','登临川仙台观南亭','李翔','唐','独倚危栏爱景晴，
古松坛殿半阴横。
东山有路干云险，
汝水无波到底清。
归洞斗龙收雨脚，
拂檐行雁起秋声。
开襟正是忘机处，
不觉疏钟遍郡城。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_29','谢公石樽','李翔','唐','康乐云楼迹尚存，
竹亭犹仰古洼樽。
苔封四面迷山象，
露滴中心认酒痕。
岩月旧来曾伴饮，
涧泉今咽共谁论。
无因访得逃尧客，
求取风瓢挂石门。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_30','谢梁尊师见访不遇','李翔','唐','晓斲黄精昼未还，
岂知仙老降柴关。
一声归鹤唳江口，
数片白云遗竹间。
怅望有惭劳羽驾，
差池不得礼冰颜。
秋风独倚书斋立，
遥想真晖对暮山。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_31','献龙虎山张天师','李翔','唐','东汉天师直下孙，
久依科戒住玄门。
寰中有位逢皆拜，
世上无人见不尊。
三洞吏兵潜稽首，
六宫魔幻暗销魂。
可能授与长生箓，
浩劫铭肌敢忘恩。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_32','题金泉山谢自然传后','李翔','唐','暂谪归天固有程，
虚皇还召赴三清。
箫歌近向峰头合，
羽驾低临洞口迎。
自换玉衣期上帝，
岂关金格注生名。
门人未得随师去，
云外空闻好住生。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_33','题麻姑山庙','李翔','唐','险翠峨霄压上游，
大仙曾向此幽求。
云埋三级坛空在，
月照千寻水自流。
偃盖鹤还清露滴，
古池龙睡碧莲秋。
桑田未必翻为海，
香火何人解继修。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_34','魏夫人归大霍山','李翔','唐','受锡南归大霍宫，
众真同会绛房中。
裘披凤锦千花丽，
旆绰龙霞八景红。
羽帔俨排三洞客，
仙歌凝韵九天风。
元君未许人先起，
更待云璈一曲终。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_35','魏夫人受大洞真经','李翔','唐','太极仙公降上清，
为传三十九章经。
先教稽首承明诏，
次遣斋心向洞冥。
妙句只令岩下读，
真文不许世间听。
宝函钿轴披寻遍，
始驾龙车谒帝庭。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_36','小有王君别西域总真','李翔','唐','从事明真入洞台，
便祛秋骨致仙材。
绛宫玄圃皆寻遍，
龟岫龙洲尽到来。
闻启玉皇过九奏，
教诏金液语千回。
谓言得道轻离别，
重感师恩泣更哀。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_37','童子山','李翔','唐','童子山形也不孤，
势疑高拱耸仙都。
云生石肘如擎帔，
月到岩心似捧壶。
岂可绕坛操凤节，
争教侍烛秉麟须。
桑田若更成东海，
始肯随师化此躯。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_38','舞凤石','李翔','唐','远见麻姑戏瑞禽，
每来教舞此坛心。
基离地面三千丈，
势倚云根一万寻。
烟海日摇双翅影，
洞天风散九韶音。
自从越叟分明说，
便想罗浮直至今。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_39','郊庙歌辞 让皇帝庙乐章 亚献终献','李纾','南汉','秩礼有序，
和音既同。
九仪不忒，
三揖将终。
孝感藩后，
相维辟公。
四时之典，
永永无穷。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_40','郊庙歌辞 让皇帝庙乐章 迎俎','李纾','南汉','祀盛体荐，
礼协粢盛。
方周假庙，
用鲁纯牲。
捧彻祗敬，
击拊和鸣。
受釐归胙，
既戒而平。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_41','郊庙歌辞 让皇帝庙乐章 迎神','李纾','南汉','皇矣天宗，
德先王季。
因心则友，
克让以位。
爰命有司，
式遵前志。
神其降灵，
昭飨祀事。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_42','郊庙歌辞 让皇帝庙乐章 酌献','李纾','南汉','八音具举，
三寿既盥。
洁兹宗彝，
瑟彼圭瓒。
兰肴重错，
椒醑飘散。
降胙维城，
永为藩翰。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_43','郊庙歌辞 让皇帝庙乐章 奠币','李纾','南汉','惟帝时若，
去而上仙。
祀用商舞，
乐备宫悬。
白璧加荐，
玄纁告虔。
子孙拜后，
承兹吉蠲。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_44','郊庙歌辞 德明兴圣庙乐章 亚献终献','李纾','南汉','惟清惟肃，
靡闻靡见。
举备九成，
俛终三献。
庆彰曼寿，
胙彻嘉荐。
瘗玉埋牲，
礼神斯遍。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_45','郊庙歌辞 德明兴圣庙乐章 兴圣酌献','李纾','南汉','閟宫静谧，
合乐周张。
泰尊始献，
百末重觞。
震澹存诚，
庶几迪尝。
遥源之祚，
天汉灵长。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_46','郊庙歌辞 德明兴圣庙乐章 迎俎','李纾','南汉','盛牲实俎，
涓选休成。
鼎煁阳燧，
玉盥阴精。
有飶嘉豆，
既和大羹。
侑以清乐，
细齐人情。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_47','郊庙歌辞 德明兴圣庙乐章 迎神','李纾','南汉','元尊九德，
佐尧光宅。
烈祖太宗，
方周作伯。
响怀霜露，
乐变金石。
白云清风，
髣髴来格。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_48','郊庙歌辞 德明兴圣庙乐章 送神','李纾','南汉','元精回复，
灵贶繁滋。
风洒兰路，
云摇桂旗。
高丘缅邈，
凉部逶迟。
瞻望靡及，
缠绵永思。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_49','郊庙歌辞 德明兴圣庙乐章 登歌奠币','李纾','南汉','四时有典，
百事来祭。
尊祖奉宗，
严禋大帝。
礼先苍璧，
奠币黝制。
于斯万年，
熙成帝系。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_50','郊庙歌辞 德明兴圣庙乐章 德明酌献','李纾','南汉','清庙奕奕，
和乐雍雍。
器尊牺象，
礼属宗公。
白水方祼，
黄流在中。
谟明之德，
万古清风。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_4_51','钓鱼不得','李舜弦','五代','尽日池边钓锦鳞，
芰荷香里暗消魂。
依稀纵有寻香饵，
知是金钩不肯吞。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_52','随驾游青城','李舜弦','五代','因随八马上仙山，
顿隔尘埃物象闲。
只恐西追王母宴，
却忧难得到人间。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_53','蜀宫应制','李舜弦','五代','浓树禁花开后庭，
饮筵中散酒微醒。
濛濛雨草瑶阶湿，
钟晓愁吟独倚屏。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_54','题壁','李遐周','唐','燕市人皆去，
函关马不归。
若逢山下鬼，
环上系罗衣。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_55','谶句','李遐周','唐','木易若逢山下鬼，
定知此处丧金环。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_4_56','读惠山若冰师集因题故院','李骘','唐','五天何处望，
心念起皆知。
化塔留今日，
泉鸣自昔时。
古苔生石静，
秋草满山悲。
莫道声容远，
长歌白雪词。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_57','读惠山若冰师集因题故院','李骘','唐','高怀逢异境，
佳句想吟频。
月冷松溪夜，
烟浓草寺春。
浮云将世远，
清听与名新。
不见开岩日，
空为拜影人。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_58','读惠山若冰师集因题故院','李骘','唐','景物搜求歇，
山云放纵飞。
树寒烟鹤去，
池静水龙归。
暗榻尘飘满，
阴檐月到稀。
何年灯焰尽，
风动影堂扉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_59','自惠山至吴下寄酬南徐从事','李骘','唐','不接芳晨游，
独此长洲苑。
风颜一成阻，
翰墨劳空返。
悠悠汀渚长，
杳杳蘋花晚。
如何西府欢，
尚念东吴远。
瑶音动清韵，
兰思芬盈畹。
犹及九峰春，
归吟白云巘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_60','慧山寺肄业送怀坦上人','李骘','唐','流水何山分，
浮云空中遇。
我生无根株，
聚散亦难固。
忆昨斗龙春，
岩栖侣高步。
清怀去羁束，
幽境无滓污。
日落九峰明，
烟生万华暮。
兹欢未云隔，
前笑倏已故。
四时难信留，
百草换霜露。
离襟一成解，
怅抱将何谕。
惊泉有馀哀，
永日谁与度。
缅思孤帆影，
再往重江路。
去去忽悽悲，
因风暂回顾。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_61','上令狐舍人','李廓','唐','名利生愁地，
贫居岁月移。
买书添架上，
断酒过花时。
宿客嫌吟苦，
乖童恨睡迟。
近来唯俭静，
持此荅深知。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_62','杂曲歌辞','李廓','唐','金紫少年郎，
绕街鞍马光。
身从左中尉，
官属右春坊。
刬戴扬州帽，
重薰异国香。
垂鞭踏青草，
来去杏园芳。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_63','杂曲歌辞','李廓','唐','小妇教鹦鹉，
头边唤醉醒。
犬娇眠玉簟，
鹰掣撼金铃。
碧地攒花障，
红泥待客亭。
虽然长按曲，
不饮不曾听。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_64','杂曲歌辞','李廓','唐','追逐轻薄伴，
闲游不著绯。
长拢出猎马，
数换打毬衣。
晓日寻花去，
春风带酒归。
青楼无昼夜，
歌舞歇时稀。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_65','杂曲歌辞','李廓','唐','日高春睡足，
帖马赏年华。
倒插银鱼袋，
行随金犊车。
还携新市酒，
远醉曲江花。
几度归侵黑，
金吾送到家。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_66','杂曲歌辞','李廓','唐','好胜耽长行，
天明烛满楼。
留人看独脚，
赌马换偏头。
乐奏曾无歇，
杯巡不暂休。
时时遥冷笑，
怪客有春愁。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_67','杂曲歌辞','李廓','唐','遨游携艳妓，
装束似男儿。
杯酒逢花住，
笙歌簇马吹。
莺声催曲急，
春色讶归迟。
不以闻街鼓，
华筵待月移。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_68','杂曲歌辞','李廓','唐','赏春惟逐胜，
大宅可曾归。
不乐还逃席，
多狂惯衩衣。
歌人踏月起，
语燕卷帘飞。
好妇惟相妒，
倡楼不醉稀。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_69','杂曲歌辞','李廓','唐','戟门连日闭，
苦饮惜残春。
开琐通新客，
教姬屈醉人。
请歌牵白马，
自舞踏红茵。
时辈皆相许，
平生不负身。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_70','杂曲歌辞','李廓','唐','新年高殿上，
始见有光辉。
玉雁排方带，
金鹅立仗衣。
酒深和碗赐，
马疾打珂飞。
朝下人争看，
香街意气归。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_71','杂曲歌辞','李廓','唐','游市慵骑马，
随姬入坐车。
楼边听歌吹，
帘外市钗花。
乐眼从人闹，
归心畏日斜。
苍头来去报，
饮伴到倡家。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_72','送振武将军','李廓','唐','叶叶归边骑，
风头万里乾。
金装腰带重，
铁缝耳衣寒。
芦酒烧蓬煖，
霜鸿撚箭看。
黄河古戍道，
秋雪白漫漫。',NULL,'[{"Book": "《唐诗摘钞》", "Section": null, "Content": "昔人画射猎图，但作弯弓引满之状，评者谓相其神力，真有应弦而倒之势，此论画三昧也。今六句云：“霜鸿撚箭看”，亦是亏令中神理，觉老杜“赤羽千夫膳”句笨钝之甚。只绘一幅出塞图，不加题跋，笔意最佳。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗摘钞》"}, {"Book": "《增订唐诗摘钞》", "Section": null, "Content": "七八句法雄浑，求之初盛，亦不可多得。“秋雪”字更妙，非塞上早寒，何以有此？", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《增订唐诗摘钞》"}, {"Book": "《近体秋阳》", "Section": null, "Content": "格变更律肃，体平而气高。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《近体秋阳》"}, {"Book": "《唐贤小三昧集续集》", "Section": null, "Content": "英拔语不可多得（“芦酒”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐贤小三昧集续集》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_73','夏日途中','李廓','唐','树夹炎风路，
行人正午稀。
初蝉数声起，
戏蝶一团飞。
日色欺清镜，
槐膏点白衣。
无成归故里，
自觉少光辉。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_74','落第','李廓','唐','榜前潜制泪，
众里自嫌身。
气味如中酒，
情怀似别人。
煖风张乐席，
晴日看花尘。
尽是添愁处，
深居乞过春。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：入想甚远，说来却甚切（“气味”二句下）。此诗愁苦极矣。要是胸中高兴人所为，不然不如是之趣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐诗快》", "Section": null, "Content": "描绘落第苦况，无如此诗。首二语尤极悲痛。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗快》"}, {"Book": "《唐贤小三昧集续集》", "Section": null, "Content": "非身受者不知其妙（“气味”句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐贤小三昧集续集》"}, {"Book": "《石园诗话》", "Section": null, "Content": "李颍州廓《长安少年行》警句云：晓日寻花去，春风带酒归。”……《落第》云：“榜前潜制泪，众里自嫌身。气味如中酒，情怀似别人。”写得意及失意情景皆肖。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《石园诗话》"}]','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_75','杂歌谣辞 鸡鸣曲','李廓','唐','星稀月没上五更，
胶胶角角鸡初鸣。
征人牵马出门立，
辞妾欲向安西行。
再鸣引颈檐头下，
月中角声催上马。
才分曙色第三鸣，
旌旗红尘已出城。
妇人上城乱招手，
夫婿不闻遥哭声。
长恨鸡鸣别时苦，
不遣鸡栖近窗户。',NULL,'[{"Book": "《唐贤小三昧集续集》", "Section": null, "Content": "直截得妙，语意亦近张、王。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐贤小三昧集续集》"}, {"Book": "《唐诗归》", "Section": null, "Content": "钟云：直写节次，无限情事委折其中（“才分曙色”句下）。谭云：乐府妙想。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}]','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_76','猛士行','李廓','唐','战鼓惊沙恶天色，
猛士虬髯眼前黑。
单于衣锦日行兵，
阵头走马生擒得。
幽并少年不敢轻，
虎狼窟里空手行。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_77','镜听词','李廓','唐','匣中取镜辞灶王，
罗衣掩尽明月光。
昔时长著照容色，
今夜潜将听消息。
门前地黑人来稀，
无人错道朝夕归。
更深弱体冷如铁，
绣带菱花怀里热。
铜片铜片如有灵，
愿照得见行人千里形。',NULL,'[{"Book": "《唐诗归》", "Section": null, "Content": "钟云：“错道”二字如何入想（“无人错道”句下）。谭云：悲苦在一“热”字（“绣带菱花”句下）。钟云：“镜听”说向“照”上，无聊之甚（“愿得照见”句下）。钟云：王建亦有此词，说向喜边，此专说向悲边。苦情则一，时此诗入景更深婉。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐诗归》"}, {"Book": "《唐风定》", "Section": null, "Content": "与仲初作，俱连城之壁。别生一意作结，妙绝（末句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《唐风定》"}, {"Book": "《王闿运手批唐诗选》", "Section": null, "Content": "苦语实景，想系曾怀镜来（“更深弱体”二句下）。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《王闿运手批唐诗选》"}]','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_78','复谑廷裕','李搏','唐','曾随风水化凡鳞，
安上门前一字新。
闻道蜀江风景好，
不知何似杏园春。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_79','贺裴廷裕蜀中登第诗','李搏','唐','铜梁千里曙云开，
仙箓新从紫府来。
天上已张新羽翼，
世间无复旧尘埃。
嘉祯果中君平卜，
贺喜须斟卓氏杯。
应笑戎藩刀笔吏，
至今泥滓曝鱼鳃。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_80','杂曲歌辞 东飞伯劳歌','李暇','唐','秦王龙剑燕后琴，
珊瑚宝匣镂双心。
谁家女儿抱香枕，
开衾灭烛愿侍寝。
琼窗半上金镂帱，
轻罗掩面不遮羞。
青绮帏中坐相忆，
红鸾镜里见愁色。
檐花照月莺对栖，
空将可怜暗中啼。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_81','相和歌辞','李暇','唐','何处期郎游，
小苑花台间。
相忆不可见，
且复乘月还。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_82','相和歌辞','李暇','唐','罗敷初总髻，
蕙芳正娇小。
月落始归船，
春眠恒著晓。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_83','相和歌辞','李暇','唐','别来花照路，
别后露垂叶。
歌舞须及时，
如何坐悲妾。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_84','相和歌辞 碧玉歌','李暇','唐','碧玉上宫妓，
出入千花林。
珠被玳瑁床，
感郎情意深。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_4_85','无题','李溟','唐','乔木挂斗邑，
水驿坏门开。
向月片帆去，
背云行雁来。
晚年名利迹，
宁免路岐哀。
前计不能息，
若为玄鬓回。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_86','咏愁','李滂','唐','应缘心里难停住，
化作新丝出鬓边。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_4_87','亡后见形诗','李煜','南唐','异国非所志，
烦劳殊清闲。
惊涛千万里，
无乃见钟山。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_88','书灵筵手巾','李煜','南唐','浮生共憔悴，
壮岁失婵娟。
汗手遗香渍，
痕眉染黛烟。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_89','书琵琶背','李煜','南唐','侁自肩如削，
难胜数缕绦。
天香留凤尾，
馀煖在檀槽。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_90','梅花','李煜','南唐','失却烟花主，
东君自不知。
清香更何用，
犹发去年枝。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_91','赐宫人庆奴','李煜','南唐','风情渐老见春羞，
到处消魂感旧游。
多谢长条似相识，
强垂烟态拂人头。',NULL,'[{"Book": "《西溪丛语》", "Section": null, "Content": "毕景儒有李重光黄罗扇，写诗一首……后细字云“赐庆奴”。庆奴似宫人小字，诗似柳诗。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《西溪丛语》"}, {"Book": "《六砚斋三笔》", "Section": null, "Content": "后主于黄罗扇上书一诗，赐宫人庆奴……。宋时犹传玩贵家，今亡矣。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "《六砚斋三笔》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_92','感怀','李煜','南唐','又见桐花发旧枝，
一楼烟雨暮凄凄。
凭阑惆怅人谁会，
不觉潸然泪眼低。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_93','感怀','李煜','南唐','层城无复见娇姿，
佳节缠哀不自持。
空有当年旧烟月，
芙蓉城上哭蛾眉。',NULL,'[{"Book": "马令《南唐书》", "Section": null, "Content": "后主昭惠后周氏，大司徒宗之女甫十九岁，归于王宫。通书史，善音律，尤工琵琶。元宗赏其艺，取所御琵琶，时谓之烧槽者赐焉。后主即位，册为国后。后主尝演《念家山破》，后复作《邀醉舞》、《恨来迟新破》，皆行于时。季子仲宣，后尤钟爱，忽暴疾卒，后病遂亟，以元宗所赐琵琶及系臂玉环亲遗后主，沐浴正妆，口内含玉，殂于瑶光殿之西室，享年二十九。后主哀苦骨立，杖而后起，每于花朝月夕，无不伤怀。如“又见桐花发旧枝……”，皆因后作。", "IsComment": false, "ReferrenceUrls": null, "FullPath": "马令《南唐书》"}]','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_94','题金楼子后','李煜','南唐','牙签万轴裹红绡，
王粲书同付火烧。
不于祖龙留面目，
遗篇那得到今朝。',NULL,'','{"preface": "梁孝元谓：「王仲宣昔在荆州，著书数十篇。荆州坏，尽焚其书。今在者一篇，知名之士咸重之。见虎一毛，不知其斑。后西魏破江陵，帝亦尽焚其书，曰：『文武之道，尽今夜矣！』何荆州坏焚书二语，先后一辙也，诗以慨之。", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_95','九月十日偶书','李煜','南唐','晚雨秋阴酒乍醒，
感时心绪杳难平。
黄花冷落不成艳，
红叶飕飗竞鼓声。
背世返能厌俗态，
偶缘犹未忘多情。
自从双鬓斑斑白，
不学安仁却自惊。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_96','秋莺','李煜','南唐','残莺何事不知秋，
横过幽林尚独游。
老舌百般倾耳听，
深黄一点入烟流。
栖迟背世同悲鲁，
浏亮如笙碎在缑。
莫更留连好归去，
露华凄冷蓼花愁。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_97','送邓王二十弟从益牧宣城','李煜','南唐','且维轻舸更迟迟，
别酒重倾惜解携。
浩浪侵愁光荡漾，
乱山凝恨色高低。
君驰桧楫情何极，
我凭阑干日向西。
咫尺烟江几多地，
不须怀抱重凄凄。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_98','挽辞','李煜','南唐','珠碎眼前珍，
花凋世外春。
未销心里恨，
又失掌中身。
玉笥犹残药，
香奁已染尘。
前哀将后感，
无泪可沾巾。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_99','挽辞','李煜','南唐','艳质同芳树，
浮危道略同。
正悲春落实，
又苦雨伤丛。
秾丽今何在？
飘零事已空。
沈沈无问处，
千载谢东风。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_100','病中书事','李煜','南唐','病身坚固道情深，
宴坐清香思自任。
月照静居唯捣药，
门扃幽院只来禽。
庸医懒听词何取，
小婢将行力未禁。
赖问空门知气味，
不然烦恼万涂侵。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_101','病中感怀','李煜','南唐','憔悴年来甚，
萧条益自伤。
风威侵病骨，
雨气咽愁肠。
夜鼎唯煎药，
朝髭半染霜。
前缘竟何似，
谁与问空王。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_102','病起题山舍壁','李煜','南唐','山舍初成病乍轻，
杖藜巾褐称闲情。
炉开小火深回暖，
沟引新流几曲声。
暂约彭涓安朽质，
终期宗远问无生。
谁能役役尘中累，
贪合鱼龙搆强名。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_103','悼诗','李煜','南唐','永念难消释，
孤怀痛自嗟。
雨深秋寂莫，
愁引病增加。
咽绝风前思，
昏濛眼上花。
空王应念我，
穷子正迷家。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_104','梅花','李煜','南唐','殷勤移植地，
曲槛小阑边。
共约重芳日，
还忧不盛妍。
阻风开步障，
乘月溉寒泉。
谁料花前后，
蛾眉却不全。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_105','渡中江望石城泣下','李煜','南唐','江南江北旧家乡，
三十年来梦一场。
吴苑宫闱今冷落，
广陵台殿已荒凉。
云笼远岫愁千片，
雨打归舟泪万行。
兄弟四人三百口，
不堪闲坐细思量。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_106','木兰花','李煜','南唐','晚妆初了明肌雪，
春殿嫔娥鱼贯列。
凤箫声断水云闲，
重按霓裳歌遍彻。
临风谁更飘香屑，
醉拍阑干情未切。
归时休放烛花红，
待蹋马蹄清夜月。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_107','破阵子','李煜','南唐','四十年来家国，
三千里地山河。
凤阙龙楼连霄汉，
玉树琼枝作烟萝，
几曾识干戈？
一旦归为臣虏，
沈腰潘鬓销磨。
最是苍黄辞庙日，
教坊独奏别离歌，
垂泪对宫娥。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_108','渔父','李煜','南唐','浪花有意千里雪，
桃花无言一队春。
一壶酒，
一竿身，
快活如侬有几人。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_109','渔父','李煜','南唐','一棹春风一叶舟，
一纶茧缕一轻钩。
花满渚，
酒满瓯，
万顷波中得自由。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_110','谢新恩','李煜','南唐','樱花落尽阶前月，
象床愁倚薰笼。
远似去年今日，
恨还同。
双鬟不整云憔悴，
泪沾红抹胸。
何处相思苦，
纱窗醉梦中。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_111','谢新恩','李煜','南唐','樱花落尽春将困，
秋千架下归时。
漏暗斜月迟迟，
花在枝。
彻晓纱窗下，
待来君不知。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_112','谢新恩','李煜','南唐','冉冉秋光留不住，
满阶红叶暮。
又是过重阳，
台榭登临处。
茱萸香堕，
紫菊气，
飘庭户，
晚烟笼细雨。
雍雍新雁咽寒声，
愁恨年年长相似。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_113','锦堂春','李煜','南唐','昨夜风兼雨，
帘帏飒飒秋声。
烛残漏滴频欹枕，
起坐不能平。
世事漫随流水，
算来一梦浮生。
醉乡路稳宜频到，
此外不堪行。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_114','一斛珠','李煜','南唐','晚妆初过，
沈檀轻注些儿个，
向人微露丁香颗。
一曲清歌，
暂引樱桃破。
罗袖裛残殷色可，
杯深旋被香醪涴，
绣床斜凭娇无那。
烂嚼红茸，
笑向檀郎唾。',NULL,'[{"Book": null, "Section": null, "Content": "1.沈（chen2）檀--浅绛色的唇膏。轻注：轻点。<br/>2.丁香颗--代称女子的舌头。<br/>3.樱桃破--代指张开小口。<br/>4.“罗袖”句--可：隐约。<br/>5.无那--无奈。<br/>6.红茸--红色的丝线。<br/>7.檀郎--古代妇女称呼自己所爱的男子为檀郎。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_115','忆江南','李煜','南唐','多少恨，
昨夜梦魂中。
还似旧时游上苑，
车如流水马如龙，
花月正春风。',NULL,'[{"Book": null, "Section": null, "Content": "    ①上苑：古代皇帝的花园。<br/>    ②车如流水马如龙：极言车马众多。<br/><br/>    【评解】<br/>    这首记梦小词，是李煜降宋被囚后的作品。抒写了梦中重温旧时游娱生活的欢乐和梦醒之后的悲恨。以梦中的乐景抒写现实生活中的哀情。“车如流水马如龙，花月正春风。”游乐时环境的优美，景色的绮丽，倾注了诗人对往昔生活的无限深情。这首小词，“深哀浅貌，短语长情”，在艺术上达到高峰。“以梦写醒”、“以乐写愁”、“以少胜多”的高妙手法，使这首小词获得耐人寻味的艺术生命。<br/><br/>    【集评】<br/>    张燕瑾《唐宋词选析》：统观这首小词，构思新颖，环环相扣，通首都用白描手法，语言明净流畅。<br/>    《唐宋词鉴赏集》：李煜笔下这个欢乐而又使他悲苦的梦，可以使作品置身于唐宋诗词作家创造的形形色色的“梦”的画廊之中。<br/>    俞陛云《唐五代两宋词选释》：“车水马龙”句为时传诵。当年之繁盛，今日之孤凄，欣戚之怀，相形而益见。<br/>    陈廷焯《别调集》卷一云：后主词一片忧思，当领会于声调之外，君人而为此词，欲不亡国也得乎？", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_116','忆江南','李煜','南唐','多少泪，
沾袖复横颐。
心事莫将和泪滴，
凤笙休向月明吹，
肠断更无疑。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_117','忆江南','李煜','南唐','闲梦远，
南国正芳春。
船上管弦江面绿，
满城飞絮混轻尘，
愁杀看花人。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_118','忆江南','李煜','南唐','闲梦远，
南国正清秋。
千里江山寒色暮，
芦花深处泊孤舟，
笛在月明楼。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_119','长相思','李煜','南唐','一重山，
两重山。
山远天高烟水寒，
相思枫叶丹。
菊花开，
菊花残。
塞雁高飞人未还，
一帘风月闲。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_120','长相思','李煜','南唐','云一緺，
玉一梭。
澹澹衫儿薄薄罗，
轻颦双黛螺。
秋风多，
雨如和。
帘外芭蕉三两窠，
夜长人奈何。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_121','后庭花破子','李煜','南唐','玉树后庭前，
瑶草妆镜边。
去年花不老，
今年月又圆。
莫教偏，
和月和花，
天教长少年。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_122','阮郎归','李煜','南唐','东风吹水日衔山，
春来长是闲。
落花狼藉酒阑珊，
笙歌醉梦间。
春睡觉，
晚妆残，
无人整翠鬟。
留连光景惜朱颜，
黄昏独倚阑。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_123','应天长','李煜','南唐','一钩初月临妆镜，
蝉鬓凤钗慵不整。
重帘静，
层楼迥，
惆怅落花风不定。
柳堤芳草径，
梦断辘轳金井。
昨夜更阑酒醒，
春愁过却病。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_124','采桑子','李煜','南唐','辘轳金井梧桐晚，
几树惊秋，
昼雨如愁，
百尺虾须上玉钩。
琼窗春断双蛾皱，
回首边头，
欲寄鳞游，
九曲寒波不溯流。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_125','采桑子','李煜','南唐','亭前春逐红英尽，
舞态徘徊，
细雨霏微，
不放双眉时暂开。
绿窗冷静芳音断，
香印成灰，
可奈情怀，
欲睡朦胧入梦来。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_126','青玉案','李煜','南唐','梵宫百尺同云护，
渐白满苍苔路。
破腊梅花香早露。
银涛无际，
玉山万里，
寒罩江南树。
鸦啼影乱天将暮，
海月纤痕映烟雾。
修竹低垂孤鹤步。
杨花风弄，
鹅毛天剪，
总是诗人误。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_127','临江仙','李煜','南唐','樱桃落尽春归去，
蝶翻轻粉双飞。
子规啼月小楼西，
玉钩罗幕，
惆怅暮烟垂。
别巷寂寥人散后，
望残烟草低迷。
炉香闲袅凤皇儿，
空持罗带，
回首恨依依。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_128','临江仙','李煜','南唐','秦楼不见吹箫女，
空馀上苑风光。
粉英金蕊自低昂，
东风恼我，
才发一衿香。
琼窗梦留残日，
当年得恨何长。
碧阑干外映垂杨，
暂时相见，
如梦懒思量。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_129','登大观楼迟门生曾孝廉不至','黎永赞','清','对此茫茫大九州，
西南天地小勾留。
湖山有福邀青眼，
诗酒多情误白头。
能自欢娱为上策，
最难把握是中流。
春风何独私曾点，
不遣同登百尺楼。',NULL,'','{"preface": "", "note": ""}','律诗','hefengbao/jingmo-data3'),
('rd3_4_130','相见欢','李煜','南唐','林花谢了春红，
太悤悤。
无奈朝来寒雨，
晚来风。
胭脂泪，
相留醉，
几时重。
自是人生长恨，
水长东。',NULL,'[{"Book": null, "Section": null, "Content": "[1]胭脂泪：指女子的眼泪。女子脸上搽有胭脂泪水流经脸颊时沾上胭脂的红色，故云。<br />[2]几时重：何时再度相会。<br /><br />此词将人生失意的无限怅恨寄寓在对暮春残景的描绘中，是即景抒情的典范之作。<br />起句“林花谢了春红”，即托出作者的伤春惜花之情；而续以“太匆匆”，则使这种伤春惜花之情得以强化。狼藉残红，春去匆匆；而作者的生命之春也早已匆匆而去，只留下伤残的春心和破碎的春梦。因此，“太匆匆”的感慨，固然是为林花凋谢之速而发，但其中不也糅合了人生苦短、来日无多的喟叹，包蕴了作者对生命流程的理性思考？<br />“无奈朝来寒雨晚来风”一句点出林花匆匆谢去的原因是风雨侵龚，而作者生命之春的早逝不也是因为过多地栉风沐雨？所以，此句同样既是叹花，亦是自叹。“无奈”云云，充满不甘听凭外力摧残而又自恨无力改变生态环境的感怆。<br />换头“胭脂泪”三句，转以拟人化的笔墨，表现作者与林花之间的依依惜别之情。这里，一边是生逢末世，运交华盖的失意人，一边是盛时不再、红消香断的解语花，二者恍然相对，不胜缱绻。“胭脂泪”，遥按上片“林花谢了春红”句，是从杜甫《曲江对雨》诗“林花著雨胭脂湿”变化而来。林花为风侵欺，状如胭脂。“胭脂泪”者，此之谓也。但花本无泪，实际上是惯于“以我观物”的作者移情于彼，使之人格化——作者身历世变，泣血无泪，不亦色若胭脂？<br />“相留醉”，一作“留人醉”，花固怜人，人亦惜花；泪眼相向之际，究竟是人留花抑或花留人，已惝恍难分。着一“醉”字，写出彼此如醉如痴、眷变难舍的情态，极为传神，而“几时重”则吁出了人与花共同的希冀和自知希冀无法实现的怅惘与迷茫。<br />结句“自是人生长恨水长东”，一气呵成益见悲慨。“人生长恨”似乎不仅仅是抒写一已的失意情怀，而涵盖了整个人类所共有的生命的缺憾，是一种融汇和浓缩了无数痛苦的人生体验的浩叹。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_131','相见欢','李煜','南唐','无言独上西楼，
月如钩。
寂寞梧桐深院，
锁清秋。
剪不断，
理还乱，
是离愁。
别是一般滋味，
在心头。',NULL,'[{"Book": null, "Section": null, "Content": "亡国之音哀以思——李煜两首《相见欢》的解读<br/><br/>一、李煜生平及词风衍演  <br/><br/>李煜（937－978）公元961年即位，史称南唐后主。他登位之时，宋已代周建国，南唐形势风雨飘摇。他在对宋委屈求全中过了十几年苟安生活。南唐为宋灭之后，他被俘到汴京，过了约两年囚徒生活，终为太宗赐鸩毒杀。  <br/><br/>李煜在政治上十分无能，文艺上却颇有成就，工书善画，妙解音律，尤工于词。他的创作分为前后两个阶段：前期不修政事，纵情于吟咏宴游，笙歌燕舞，为了使宫女的舞姿更加曼妙婀娜，荒唐病态竟至于让宫女束脚，戕害中国女子裹脚陋习便起于其人。他这一时期的词作大都反映了他荒淫奢靡的官廷生活，这些词虽在技巧上已日臻成熟，实则为南朝宫体和花间词风的承续。后期则为入宋之后，此时，他逐渐从醉生梦死中清醒过来，对屈辱的拘囚生活极为愤懑感伤，他的词开始转向抒奏亡国之音，倾泻其“日夕以眼泪洗面”的深哀巨恸，他的词有了打动人心的恒久的艺术力量。可以说，亡国使他丢掉了皇帝的宝座，却使他在词的创作上获取了巨大的成就，诚如清人王国维评价：“词至李后主而眼界始大，感慨遂深，遂变伶工之词为士大夫之词。”便是对他文学地位的中肯评价。  <br/><br/>二、《相见欢》的“细读”  <br/><br/>西方新批评学派在解读诗歌时采纳重视文字本身在作品中的作用的“细读”方式，他们认为，文字是组成篇什的基础，而文字表现出的形象、肌理、色调、语法乃是评说一首诗歌的重要依据。下面，笔者就用这种“细读”的形式对两首《相见欢》的意义加诸简评。  <br/><br/>（一）《相见欢·林花谢了春红》  <br/><br/>1、“林花”：满林花树；“谢了”：表现一种美好事物－－美好之节、美好之花、美好之色－－零落凋残的悲慨；“春红”：代落英；“太匆匆”：花开短促，体现为对美的凋零的伤悼之感。  <br/><br/>2、“无奈朝来寒雨往来风”：花谢匆匆之因。“朝”与“晚”、“雨”与“风”的对举，极尽朝暮风雨摧残施虐的无可抗争之悲绪。  <br/><br/>3、“胭脂泪”：承上文之“春红”，悲极艳绝，确有杜甫“林花著雨胭脂湿”的意蕴；“留人醉”：悲伤凄惜，人迷心醉，是“花”对赏花者的相留，还是“人”对赏花者的相留？或可作多义诠解；“几时重？”：犹言“何时可再？”，用花之凋谢与人之离别展现了一种难以挽回的痛苦惋叹。  <br/><br/>4、“自是人生长恨水长东”：“长恨”、“长东”，悲绪难平。系悲沈恨极的哀切之辞。  <br/><br/>（二）《相见欢·无言独上西楼》  <br/><br/>1、“无言独上西楼”：“无言”，无尽思绪，无可倾诉；“独上西楼”：登高问月，无人倾诉、心境落寞的行为观照；“月如钩”：寂寞清愁的意象，月圆必缺，载荷着人生的无常之悲。  <br/><br/>2、“寂寞梧桐深院锁清秋”：种着梧桐树的寂静庭院为秋色笼罩（梧桐，古有“梧桐树，三更雨”、“疏雨滴梧桐”等句），“寂寞梧桐”，似有人树泯合之感；“深院”，庭院深深，音讯隔绝杳无；“清秋”：背景，为通篇充溢的“离愁”愁起之由。全句摹画了一幅意境朦胧、浸染着哀愁的图画。  <br/><br/>3、“剪不断，理还乱，是离愁”：表现了心宇深处深深的寂寞、万般的无奈和无法排遣的离愁。  <br/><br/>4、“别是一般滋味在心头”：“别是一般滋味”指离愁，即“离愁在心头”之意。如果说前文还用“剪”和“理”的动作对离愁加以形象摹刻，本句则将离愁写得无可形状、无以陈述，为更深一层的写法。  <br/><br/>三、《相见欢》的喻况  <br/><br/>“尼采谓：‘一切文字，余爱以血书者。’后主之词，真所谓以血书者也”。（王国维《人间词话》卷上）对任何一个作家的作品的解读，都离不开对其本人生平和思想的了解，因为在作品中，无一例外地蕴藉着作者自身的爱憎情感和思想观念，所以法朗士说“文学作品都是作家的自叙传”。这句话是否绝对我们姑且不论，但其某种程度上反映了文学创作活动的本质是毋庸置疑的。的确，作品往往折射着作者本人的经验体悟和身世感发，李煜正是以他的心和血才浇沥出这两首《相见欢》。  <br/><br/>“林花”一词，表面上是伤春咏别，但细作探求，“人生长恨水长东”的深切悲慨，决非一般闺怨、离情，其“伤春咏别”，很难说没有托意：上片惜花之意，实是自悲身世，朝雨、晚风，摧残不已；下片念泪留醉尚且不能，何况重返故国？国而“长恨”“长东”，悲慨难托难平。“无言”一词，表面上看也是悲秋咏别，但细品寻微，词中深深的寂寞、万般的无奈和无法排遣的离愁，也决非一般离别相思，而是有所喻况：上片“梧桐”，是惨遭幽闭的物象，而“深院”难道不正是囚身之喻？下片的离愁无疑可以解为去国之愁。心品之下，确可品出“亡国之音”的况味，难怪宋人黄升评注：“此词最凄惋，可谓‘亡国之者哀以思’。”正因为如此，我们可以说，李煜词中所表现的情感哀伤深挚，莫不是字字见血，有如血泪凝铸而成。  <br/><br/>四、结论  <br/><br/>李煜的两首《相见欢》，虽然表面上都是写相思离别，但他作为亡国之君，受人拘囚，又何敢明目张胆地在作品中言志而表明自已“故国之恋”、“亡国之痛”的情感呢？除非他觉着活腻了。因而在作品中以“喻况”流露情感。  <br/><br/>因此，我们在赏析品读时，不仅要明白作品所写的外表情事方面的主题，更应把握作品中所流露的隐藏的某种心灵和情感的本质。  <br/><br/>同时，由于两者在内容情感上有着诸多的契合之处，甚至连标题也一样，我们当然可将它们视为关系密切姊妹篇，因而，为了使学生对李煜“无言”一词有更为深切的感悟，应将他的“林花”一词作为补充阅读材料以给学生，通过对举并读，使学生得到更为丰富的情感体验。  <br/>  <br/>邹立群\\n        ", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}, {"Book": null, "Section": null, "Content": "词名《相见欢》咏的却是离别愁。此词写作时期难定。如系李煜早年之作，词中的缭乱离愁不过属于他宫庭生活的一个插曲，如作于归宋以后，此词所表现的则应当是他离乡去国的锥心怆痛。<br />起句“无言独上西楼”，摄尽凄惋之神。“无言”者，并非无语可诉，而是无人共语。由作者“无言”、“独上”的滞重步履和凝重神情，可见其孤独之甚、哀愁之甚。本来，作者深谙“独自莫凭栏”之理，因为栏外景色往往会触动心中愁思，而今他却甘冒其“险”，又可见他对故国（或故人）怀念之甚、眷恋之甚。<br />“月如钩”，是作者西楼凭栏之所见。一弯残月映照着作者的孑然一身，也映照着他视线难及的“三千里地山河”（《破阵子》），引起他多少遐想、多少回忆？而俯视楼下，但见深院为萧飒秋色所笼罩。“寂寞梧桐深院锁清秋”，这里，“寂寞”者究竟是梧桐还是作者，已无法、也无须分辨，因为情与景已妙合无垠。<br />过片后“剪不断”三句，以麻丝喻离愁，将抽象的情感加以具象化，历来为人们所称道，但更见作者独诣的还是结句：“别是一般滋味在心头”。<br />诗词家借助鲜明生动的艺术形象来表现离愁时，或写愁之深，如李白《远离别》：“海水直下万里深，谁人不言此愁古”；或写愁之长，如李白《秋浦歌》：“白发三千丈，缘愁似个长”；或写恋之重，如李清照《武陵春》：“只恐双溪艋舟，载不动许多愁”；或写愁之多，如秦观《千秋岁》：“春去也，飞红万点愁如海”。李煜此句则写出愁之味：其味在酸咸之外，但却根植于作者的内心深处，无法驱散，历久弥鲜；舌品不得，心感方知。因此也就不用诉诸人们的视觉，而直接诉诸人们的心灵，读后使人自然地结合自身的体验而产生同感。这种写法无疑有其深至之处。<br /><br />【集评】<br />黄升《花庵词选》：此词最凄婉，所谓“亡国之音哀以思”。<br />陈廷焯《白雨斋词话》：思路凄惋，词场本色。<br />沈际飞《草堂诗余续集》：七情所至，浅尝者说破，深尝者说不破。<br />破之浅，不破之深。“别是一般滋味在心头”句妙。<br />唐圭璋《唐宋词简释》：此词写别愁，凄惋已极。“无言独上西楼”一句，叙事直起，画出后主愁容。其下两句，画出后主所处之愁境。举头见新月如钩，低头见桐阴深锁俯仰之间，万感萦怀矣。此片写景亦妙，惟其桐阴深黑，新月乃愈显明媚也。下片，因景抒情。换头三句，深刻无匹，使有千丝万缕之离愁，亦未必不可剪，不可理，此言“剪不断，理还乱”，则离愁之纷繁可知。所谓“别是一般滋味”，是无人尝过之滋味，唯有自家领略也。后主以南朝天子，而为北地幽囚；其所受之痛苦，所尝之滋味，自与常人不同，心头所交集者，不知是悔是恨，欲说则无从说起，且亦无人可说，故但云“别是一般滋味”。究竟滋味若何，后主且不自知，何况他人？此种无言之哀，更胜于痛哭流涕之哀。<br />俞陛云《唐五代两宋词选释》：后阕仅十八字，而肠回心倒，一片凄异之音，伤心人固别有怀抱。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_132','捣练子','李煜','南唐','深院静，
小庭空，
断续寒砧断续风。
无奈夜长人不寐，
数声和月到帘栊。',NULL,'[{"Book": null, "Section": null, "Content": "    ①砧（zhēn）：捣衣石。寒砧：寒夜捣帛声。古代秋来，家人捣帛为他乡游子准备寒衣。<br/>    ②栊：窗户。<br/><br/>    【评解】<br/>    秋风送来了断续的寒砧声，在小庭深院中，听得格外真切。夜深了，月光和砧声穿进帘栊，更使人联想到征人在外，勾起了绵绵的离恨和相思。因而长夜不寐，愁思百结。“砧声不断”、“月到帘栊”，从景中透露出愁情，情景交融，轻柔含蓄，耐人寻思。<br/>这首小令，语言新，意境新，给人以极美的艺术享受。<br/><br/>    【集评】<br/>    俞陛云《唐五代两宋词选释》：曲名《捣练子》，即以咏之，乃唐词本体。首二句言闻捣练之声，院静庭空，已写出幽悄之境。三句赋捣练，四、五句由闻砧者说到砧声之远递。通首赋捣练，而独夜怀人情味，摇漾于寒砧断续之中，可谓极此题能事。杨升庵谓旧本以此曲名《鹧鸪天》之后半首，尚有上半首云：“塘水初澄似玉容，所思还在别离中。谁知九月初三夜，露似珍珠月似弓。”案《鹧鸪天》调，唐人罕填之。况塘水四句，全于捣练无涉，升庵之说未确。但露珠月弓，传诵词苑，自是佳句。<br/>    王方俊《唐宋词赏析》：通篇无点题之笔，但处处写离情，情包含在景中，从景中透露出感情，极为含蓄，意境清新，是李词中内容较健康的词作。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_133','捣练子','李煜','南唐','云鬟乱，
晚妆残，
带恨眉儿远岫攒。
斜托香腮春笋懒，
为谁和泪倚阑干。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_134','浣溪沙','李煜','南唐','红日已高三丈透，
金炉次第添香兽，
红锦地衣随步皱。
佳人舞点金钗溜，
酒恶时拈花蕊嗅，
别殿遥闻箫鼓奏。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_135','浣溪沙','李煜','南唐','转烛飘蓬一梦归，
欲寻陈迹怅人非，
天教心愿与身违。
待月池台空逝水，
荫花楼阁漫斜晖，
登临不惜更沾衣。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_136','浪淘沙令','李煜','南唐','帘外雨潺潺，
春意阑珊。
罗衾不耐五更寒，
梦里不知身是客，
一晌贪欢。
独自暮凭阑，
无限江山。
别时容易见时难，
流水落花春去也，
天上人间。',NULL,'[{"Book": null, "Section": null, "Content": "[1]潺潺：形容雨声。<br />[2]阑珊：衰残。一作“将阑”。<br />[3]罗衾（音亲）：绸被子。不耐：受不了。一作“不暖”。<br />[4]身是客：指被拘汴京，形同囚徒。<br />[5]一晌（音赏）：一会儿，片刻。贪欢：指贪恋梦境中的欢乐。<br /><br />此词上片用倒叙手法，帘外雨，五更寒，是梦后事；忘却身份，一晌贪欢，是梦中事。潺潺春雨和阵阵春寒，惊醒残梦，使抒情主人公回到了真实人生的凄凉景况中来。梦中梦后，实际上是今昔之比。<br />李煜《菩萨蛮》词有句：“故国梦重归，觉来双泪垂”。所写情事与此差同。但《菩萨蛮》写得直率，此词则婉转曲折。词中的自然环境和身心感受，更多象征性，也更有典型性。<br />下片首句“独自莫凭栏”的“莫”字，有入声与去声（暮）两种读法。作“莫凭栏”，是因凭栏而见故国江山，将引起无限伤感，作“暮凭栏”，是晚眺江山遥远，深感“别时容易见时难”。两说都可通。<br />“流水落花春去也”，与上片“春意阑珊”相呼应，同时也暗喻来日无多，不久于人世。“天上人间”句，颇感迷离恍惚，众说纷纭。其实语出白居易《长恨歌》：“但教心似金钿坚，天上人间会相见。”“天上人间”，本是一个专属名词，并非天上与人间并列。李煜用在这里，似指自已的最后归宿。<br />应当指出，李煜词的抒情特色，就是善于从生活实感出发，抒写自已人生经历中的真切感受，自然明净，含蓄深沉。这对抒情诗来说，原是不假外求的最为本色的东西。因此他的词无论伤春伤别，还是心怀故国，都写得哀感动人。同时，李煜又善于把自已的生活感受，同高度的艺术概括力结合起来。身为亡国之君的李煜，在词中很少作帝王家语，倒是以近乎普通人的身份，诉说自已的不幸和哀苦。这些词就具有了可与人们感情上相互沟通、唤起共鸣的因素。《虞美人》（春花秋月何时了）如此，此词亦复如此。<br />即以“别时容易见时难”而言，便是人们在生活中通常会经历到是一种人生体验。与其说它是帝王之伤别，无宁说它概括了离别中的人们的普遍遭遇。李煜词大多是四五十字的小令，调短字少，然包孕极富，寄慨极深，没有高度的艺术概括力是做不到的。<br /><br />【集评】<br />《乐府纪闻》：后主归家后与故宫人书云：“梦里不知身是客，一晌贪欢，“流水落花春去也，天上人间”……旧臣闻之，有泣下者。七夕在赐第作乐。太宗闻之怒，更得其词，故有赐牵机药之事。<br />蔡绦《西清诗话》：诗人（李煜）归宋后，“每怀故国，且念嫔妾散落，郁郁不自聊。”“尝作长短句（即指此词），含思凄惋，未几下世。”<br />王方俊《唐宋词赏析》：这首词的艺术成就是很高的，自然率真，直写观感，直抒胸臆，因之有极强的艺术感染力。它不仅在旧时曾为人传诵，现在看来也是我国诗歌艺术宝库中的一件珍品。<br />俞陛云《唐五代两宋词选释》：言梦中之欢，益见醒后之悲，昔日歌舞《霓裳》，不堪回首。结句“天上人间”三句，怆然欲绝：此归朝后所作。尤极凄黯之音，如峡猿之三声肠断也。<br />唐圭璋《唐宋词简释》：此首殆后主绝笔，语意惨然。五更梦回，寒雨潺潺，其境之黯淡凄凉可知。“梦里”两句，忆梦中情事，尤觉哀痛。换头宕开，两句自为呼应，所以“独自莫凭栏”者，盖因凭阑见无限江山，又引起无限伤心也。此与“心事莫将和泪说，凤笙休向泪时吹”，同为悲愤已极之语。“别时”一句，说出过去与今天之情况。自知相见无期，而下世亦不久矣。故“流水”两句，即承上中说不久于人世之意，水流尽矣，花落尽矣，春归去矣，而人亦将亡矣。将四种了语，并合一处作结，肝肠断绝，遗恨千古。<br />《南唐二主词汇笺》引郭麟云：绵邈飘忽之音，最为感人之至。李后主之“梦里不知身是客，一晌贪欢”，所以独绝也。<br />王闿运《湘绮楼词选》：高妙超脱，一往情深。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_137','浪淘沙令','李煜','南唐','往事只堪哀，
对景难排。
秋风庭院藓侵阶，
一桁珠帘闲不卷，
终日谁来。
金剑已沈埋，
壮气蒿莱。
晚凉天净月华开，
想得玉楼瑶殿影，
空照秦淮。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_138','望远行','李煜','南唐','碧砌花光照眼明，
朱扉长日镇长扃。
馀寒欲去梦难成，
炉香烟冷自亭亭。
辽阳月，
秣陵砧，
不传消息但传情。
黄金台下忽然惊，
征人归日二毛生。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_139','清平乐','李煜','南唐','别来春半，
触目愁肠断。
砌下落梅如雪乱，
拂了一身还满。
雁来音信无凭，
路遥归梦难成。
离恨却如春草，
更行更远还生。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_140','菩萨蛮','李煜','南唐','花明月暗笼轻雾，
今宵好向郎边去。
刬袜步香阶，
手提金缕鞋。
画堂南畔见，
一晌偎人颤。
好为出来难，
教君恣意怜。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_141','菩萨蛮','李煜','南唐','蓬莱院闭天台女，
画堂昼寝无人语。
抛枕翠云光，
绣衣闻异香。
潜来珠锁动，
惊觉鸳鸯梦。
慢脸笑盈盈，
相看无限情。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_142','菩萨蛮','李煜','南唐','铜簧韵脆锵寒竹，
新声慢奏移纤玉。
眼色暗相钩，
秋波横欲流。
雨云深绣户，
来便谐衷素。
宴罢又成空，
梦迷春睡中。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_143','菩萨蛮','李煜','南唐','人生愁恨何能免，
消魂独我情何限。
故国梦重归，
觉来双泪垂。
高楼谁与上，
长记秋晴望。
往事已成空，
还如一梦中。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_144','喜迁莺','李煜','南唐','晓月坠，
宿云微，
无语枕频欹。
梦回芳草思依依，
天远雁声稀。
啼莺散，
馀花乱，
寂寞画堂深院。
片红休埽尽从伊，
留待舞人归。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_145','虞美人','李煜','南唐','风回小院庭芜绿，
柳眼春相续。
凭阑半日独无言，
依旧竹声新月，
似当年。
笙歌未散尊罍在，
池面冰初解。
烛明香暗画楼深，
满鬓清霜残雪，
思难禁。',NULL,'','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_146','虞美人','李煜','南唐','春花秋月何时了，
往事知多少。
小楼昨夜又东风，
故国不堪回首，
月明中。
雕阑玉砌应犹在，
只是朱颜改。
问君能有几多愁，
恰似一江春水，
向东流。',NULL,'[{"Book": null, "Section": null, "Content": "[1]了：了结，完结。<br />[2]砌：台阶。雕阑玉砌：指远在金陵的南唐故宫。应犹：一作“依然”。<br />[3]朱颜改：指所怀念的人已衰老。<br />[4]君：作者自称。能：或作“都”、“那”、“还”、“却”。<br /><br />此词大约作于李煜归宋后的第三年。词中流露了不加掩饰的故国之思，据说是促使宋太宗下令毒死李煜的原因之一。那么，它等于是李煜的绝命词了。<br />全词以问起，以答结；由问天、问人而到自问，通过凄楚中不无激越的音调和曲折回旋、流走自如的艺术结构，使作者沛然莫御的愁思贯穿始终，形成沁人心脾的美感效应。<br />诚然，李煜的故国之思也许并不值得同情，他所眷念的往事离不开“雕栏玉砌”的帝王生活和朝暮私情的宫闱秘事。但这首脍炙人口的名作，在艺术上确有独到之处：<br />“春花秋月”人多以美好，作者却殷切企盼它早日“了”却；小楼“东风”带来春天的信息，却反而引起作者“不堪回首”的嗟叹，因为它们都勾发了作者物是人非的枨触，跌衬出他的囚居异邦之愁，用以描写由珠围翠绕，烹金馔玉的江南国主一变而为长歌当哭的阶下囚的作者的心境，是真切而又深刻的。<br />结句“一江春水向东流”，是以水喻愁的名句，含蓄地显示出愁思的长流不断，无穷无尽。同它相比，刘禹锡的《竹枝调》“水流无限似侬愁”，稍嫌直率，而秦观《江城子》“便作春江都是泪，流不尽，许多愁”，则又说得过尽，反而削弱了感人的力量。<br />可以说，李煜此词所以能引起广泛的共鸣，在很大程度上，正有赖于结句以富有感染力和向征性的比喻，将愁思写得既形象化，又抽象化：作者并没有明确写出其愁思的真实内涵——怀念昔日纸醉金迷的享乐生活，而仅仅展示了它的外部形态——“恰似一江春水向东流。这样人们就很容易从中取得某种心灵上的呼应，并借用它来抒发自已类似的情感。因为人们的愁思虽然内涵各异，却都可以具有“恰似一江春水向东流”那样的外部形态。由于“形象往往大于思想”，李煜此词便能在广泛的范围内产生共鸣而得以千古传诵了。<br /><br />【集评】<br />俞陛云《唐五代两宋词选释》：亡国之音，何哀思之深耶？传诵禁廷，不加悯而被祸，失国者不殉宗社，而任人宰割，良足伤矣。《后山诗话》谓秦少游词“飞红万点愁如海”出于后主“一江春水”句。《野客丛书》又谓白乐天之“欲识愁多少，高于滟滪堆”、刘禹锡之“水流无限似浓愁”，为后主所祖，但以水喻愁，词家意所易到，屡见载籍，未必互相沿用。就词而论，李、刘、秦诸家之以水喻愁，不若后主之“春江”九字，真伤心人语也。<br />唐圭璋《唐宋词简释》：此首感怀故国，悲愤已极。起句，追维往事，痛不欲生！满腔恨血，喷薄而出：诚《天问》之遗也。“小楼”句承起句，缩笔吞咽；“故国”句承起句，放笔呼号。一“又”字惨甚。东风又入，可见春花秋月一时尚不得遽了。罪孽未满，苦痛未尽，仍须偷息人间，历尽磨折。下片承上，从故国月明想入，揭出物是人非之意。末以问答语，吐露心中万斛愁恨，令人不堪卒读。通首一气盘旋，曲折动荡，如怨如慕，如泣如诉。<br />王方俊《唐宋词赏析》：这首千古传诵脍炙人口的名作《虞美人》，被前人誉为“词中之帝”，是李煜囚居汴京时所作。据王轾《默记》载：“归朝（指李煜降宋后），郁郁不乐，见于词语。”本词就是抒写这种怀念故国之情，哀叹亡国之痛的情怀的。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_147','蝶恋花 春暮','李煜','南唐','遥夜亭皋闲信步，
才过清明，
渐觉伤春暮。
数点雨声风约住，
朦胧澹月云来去。
桃李依依香暗度，
谁在鞦韆，
笑里轻轻语。
一片芳心千万绪，
人间没个安排处。',NULL,'[{"Book": null, "Section": null, "Content": "此词通过作者暮春夜晚漫步时所见的景色，表达了词人起伏扬抑的伤春、相思情怀。全词以清景无限来烘托、暗示人物情感的变化，营造出一种深婉优美的意境。<br/>“遥夜”交待时间，夜色未深，但也入夜有一段时间了。所行之地是“亭皋”，城郊有宅舍亭台的地方。词人在“信步”上着一个“闲”字，点染出一幅随意举步、漫不经心的样子。“才过清明，渐觉伤春暮”是无理之语。按说“清明才过”，春光正好，词人却已经“伤春暮”了，看来“闲信步”当含有排遣内心某种积郁的用意。<br/>上片最后两句是词人耳目所见，刚刚听到几点雨声，却被春风挡住而听不到了。天上的月亮因积有云层而朦胧不明 。这两句写景 ，清新淡雅而又流转自然。<br/>过片谓这时虽说已过了桃杏盛开的花期，但余香依稀可闻。人为淡月、微云、阵阵清风、数点微雨和依稀可闻到的桃杏花香的美景所感染，那“伤春暮”的情怀暂时退却了。此处白描手法运用得当。<br/>下片二、三句词意陡转。词人遐想联翩之际，听到近处有妇女荡秋千的轻声笑语，她们说些什么听不清楚，但不断传来的莺语，对他来说是一番诱惑。<br/>结尾两句，写词人因意中人不在身边，以致常常魂牵梦萦。今夜出来漫步，便有可能出于排遣对意中人的相思之苦。举天地之大，竟无一处可以安排作者的愁绪，由此可见其徬徨、感伤与苦闷的程度之深。<br/>此词写景鲜明，抒情真挚，语言浅近，读来委婉动人，艺术上确有不凡之处。", "IsComment": false, "ReferrenceUrls": null, "FullPath": null}]','{"preface": "", "note": ""}','词','hefengbao/jingmo-data3'),
('rd3_4_148','句','李煜','南唐','迢迢牵牛星，
杳在河之阳。
粲粲黄姑女，
耿耿遥相望。
莺狂应有恨，
蝶舞已无多。
揖让月在手，
动摇风满怀。
病态如衰弱，
厌厌向五年。
衰颜一病难牵复，
晓殿君临颇自羞。
冷笑秦皇经远略，
静怜姬满苦时巡。
鬓从今日添新白，
菊是去年依旧黄。
万古到头归一死，
醉乡葬地有高原。
人生不满百，
刚作千年画。
日映仙云薄，
秋高天碧深。
乌照始潜辉，
龙烛便争秉。
凝珠满露枝，
游飏日已西。
肃穆寒初至，
九重开扇鹄。
四牖炳灯鱼，
羽觞无算酌。
倾碗更为寿，
深卮递酬宾。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_4_149','岭外守岁','李福业','唐','冬去更筹尽，
春随斗柄回。
寒暄一夜隔，
客鬓两年催。',NULL,'','{"preface": "", "note": ""}','绝句','hefengbao/jingmo-data3'),
('rd3_4_150','奉和郎中游仙岩四瀑布寄包秘监李吏部赵婺州中丞齐处州谏议十四韵','李缜','唐','符守分圭组，
放情在丘峦。
悠然造云族，
忽尔登天坛。
求古理方赜，
玩奇物不殚。
晴光散崖壁，
瑞气生芝兰。
中有四瀑水，
奔流状千般。
风云隐岩底，
雨雪霏林端。
晶晶含古色，
飕飕引晨寒。
澄潭见猿饮，
潜穴知龙盘。
坐憩苔石遍，
仰窥杉桂攒。
幽蹊创高躅，
灵药馀仙飧。
携赏喜康乐，
示文惊建安。
缣缃炳珠宝，
中外贻同官。
末调亦何为，
辄陪高唱难。
惭非御徒者，
还得依门栏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_4_151','和三乡诗','李缟','晚唐','会稽王谢两风流，
